def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the internal uniform separator, preferring one that splits
    # the grid into equal-sized panels.
    candidates = []
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1:
            candidates.append((h - 1 == 2 * r, "row", r))
    for c in range(1, w - 1):
        if len({grid[r][c] for r in range(h)}) == 1:
            candidates.append((w - 1 == 2 * c, "col", c))
    _, axis, k = max(candidates, key=lambda x: x[0])

    if axis == "row":
        a = [row[:] for row in grid[:k]]
        b = [row[:] for row in grid[k + 1:]]
    else:
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]

    shared = set(x for row in a for x in row) & set(x for row in b for x in row)
    color = next(iter(shared))
    out = [[color for _ in row] for row in a]
    for r in range(len(a)):
        for c in range(len(a[0])):
            if a[r][c] == color and b[r][c] == color:
                out[r][c] = 3
    return out
